31	  const { task, loading, error, reload } = useWorkspaceTask(
32	    workspaceId,
33	    taskId,
34	  );
35	
36	  if (loading) {
37	    return (
38	      <div
39	        data-task-tab-loading
40	        className="flex flex-1 items-center justify-center"
41	      >
42	        <p className="text-sm text-text-muted">Loading task…</p>
43	      </div>
44	    );
45	  }
46	
47	  if (error) {
48	    return (
49	      <div
50	        data-task-tab-error
51	        className="flex flex-1 flex-col items-center justify-center gap-4"
52	      >
53	        <AlertCircle className="h-8 w-8 text-danger" aria-hidden="true" />
54	        <p className="text-sm text-text-secondary">
55	          {error.message || "Failed to load task."}
56	        </p>
57	        {error.retryable && (
58	          <button
59	            type="button"
60	            onClick={reload}
61	            className="flex items-center gap-2 border border-border bg-surface px-3 py-1.5 text-xs font-medium text-text-primary transition-colors hover:bg-surface-subtle"
62	          >
63	            <RefreshCw className="h-3.5 w-3.5" aria-hidden="true" />
64	            Retry
65	          </button>
66	        )}
67	      </div>
68	    );
69	  }
70	
71	  if (!task) return null;
72	
73	  return <TaskTabContent task={task} onReload={reload} />;
74	}
75	
76	function TaskTabContent({
77	  task,
78	  onReload,
79	}: {
80	  task: TaskDetail;
81	  onReload: () => void;
82	}) {
83	  const { activeTaskTabId, closeTaskTab, goToBoard } = useWorkspaceContext();
84	  const [copied, setCopied] = useState(false);
85	  const statusColor = getStatusColor(task.status);
86	
87	  function handleBackToBoard() {
88	    if (activeTaskTabId) {
89	      closeTaskTab(activeTaskTabId);
90	      return;
91	    }
92	    goToBoard();
93	  }
94	
95	  function handleCopyId() {
96	    const textToCopy = task.task_name || task.id;
97	    if (navigator.clipboard) {
98	      navigator.clipboard.writeText(textToCopy).then(() => {
99	        setCopied(true);
100	        setTimeout(() => setCopied(false), 1500);
101	      });
102	    } else {
103	      const el = document.createElement("textarea");
104	      el.value = textToCopy;
105	      document.body.appendChild(el);
106	      el.select();
107	      document.execCommand("copy");
108	      document.body.removeChild(el);
109	      setCopied(true);
110	      setTimeout(() => setCopied(false), 1500);
111	    }
112	  }
113	
114	  return (
115	    <div
116	      data-task-tab-content
117	      className="flex h-full min-h-0 flex-col overflow-hidden bg-bg"
118	    >
119	      <header className="shrink-0 border-b border-border bg-surface px-6 py-4">
120	        <div className="flex items-center justify-between gap-3">
121	          <button
122	            type="button"
123	            data-back-to-board
124	            onClick={handleBackToBoard}
125	            aria-label="Back to board"
126	            className="flex h-8 items-center gap-1.5 border border-border bg-surface px-3 text-xs text-text-secondary transition-colors hover:bg-surface-subtle hover:text-text-primary"
127	          >
128	            <ArrowLeft className="h-3.5 w-3.5" aria-hidden="true" />
129	            Back
130	          </button>
131	          <button
132	            type="button"
133	            onClick={onReload}
134	            aria-label="Reload task"
135	            className="shrink-0 p-1 text-text-secondary transition-colors hover:text-text-primary"
136	          >
137	            <RefreshCw className="h-4 w-4" aria-hidden="true" />
138	          </button>
139	        </div>
140	        <div className="mt-4 flex min-w-0 items-start gap-2">
141	          <h1 className="min-w-0 text-xl font-semibold leading-7 text-text-primary">
142	            {task.title || task.task_name}
143	          </h1>
144	          <button
145	            type="button"
146	            data-copy-task-id
147	            onClick={handleCopyId}
148	            aria-label={`Copy task id ${task.task_name}`}
149	            title="Copy task ID"
150	            className="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center border border-border bg-surface text-text-secondary transition-colors hover:bg-surface-subtle hover:text-text-primary"
151	          >
152	            {copied ? (
153	              <Check className="h-3.5 w-3.5 text-success" aria-hidden="true" />
154	            ) : (
155	              <ClipboardCopy className="h-3.5 w-3.5" aria-hidden="true" />
156	            )}
157	          </button>
158	        </div>
159	        <div className="mt-3 flex flex-wrap items-center gap-2 text-xs">
160	          <span className="bg-chip-bg px-2 py-1 font-mono font-semibold text-text-secondary">
161	            {task.task_name}
162	          </span>
163	          <span
164	            className="px-2 py-1 font-semibold uppercase tracking-wide"
165	            style={{ backgroundColor: `${statusColor}18`, color: statusColor }}
166	          >
167	            {clientStatusLabel(task.status).toUpperCase()}
168	          </span>
169	          {task.execution?.last_updated_at && (
170	            <span className="text-text-muted">
171	              Updated {formatTimestamp(task.execution.last_updated_at)}
172	            </span>
173	          )}
174	        </div>
175	      </header>
176	
177	      <div className="flex-1 overflow-y-auto bg-surface-secondary/40 px-6 py-6">
178	        <div className="max-w-5xl space-y-8">
179	          <TaskMetadataSection task={task} />
180	          <TaskDependenciesSection task={task} />
181	          <TaskExecutionSection task={task} />
182	          <TaskPrRefsSection task={task} />
183	          <TaskActivityTimelineSection task={task} />
184	        </div>
185	      </div>
186	    </div>
187	  );
188	}
189	
190	function TaskMetadataSection({ task }: { task: TaskDetail }) {
191	  return (
192	    <section>
193	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
194	        Details
195	      </h2>
196	      <div className="grid grid-cols-2 gap-x-8 gap-y-5">
197	        <MetaField
198	          icon={<Layers className="h-4 w-4" aria-hidden="true" />}
199	          label="Repository"
200	        >
201	          {task.repo ? (
202	            <span className="text-sm text-text-primary">{task.repo}</span>
203	          ) : (
204	            <NoneValue />
205	          )}
206	        </MetaField>
207	
208	        <MetaField
209	          icon={<GitBranch className="h-4 w-4" aria-hidden="true" />}
210	          label="Branch"
211	        >
212	          {task.branch ? (
213	            <span className="break-all font-mono text-xs text-success">
214	              {task.branch}
215	            </span>
216	          ) : (
217	            <NoneValue />
218	          )}
219	        </MetaField>
220	
221	        {task.blocked_reason && (
222	          <MetaField
223	            icon={
224	              <AlertCircle className="h-4 w-4 text-danger" aria-hidden="true" />
225	            }
226	            label="Blocked Reason"
227	            fullWidth
228	          >
229	            <div
230	              data-blocked-reason
231	              className="flex items-start gap-2 border border-danger bg-danger-bg px-3 py-2"
232	            >
233	              <AlertCircle
234	                className="mt-0.5 h-4 w-4 shrink-0 text-danger"
235	                aria-hidden="true"
236	              />
237	              <span className="text-sm text-danger">{task.blocked_reason}</span>
238	            </div>
239	          </MetaField>
240	        )}
241	      </div>
242	    </section>
243	  );
244	}
245	
246	function TaskDependenciesSection({ task }: { task: TaskDetail }) {
247	  if (!task.depends_on || task.depends_on.length === 0) return null;
248	
249	  return (
250	    <section>
251	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
252	        Dependencies
253	      </h2>
254	      <div data-task-depends-on className="flex flex-wrap gap-2">
255	        {task.depends_on.map((dep) => (
256	          <span
257	            key={dep}
258	            className="bg-chip-bg px-2 py-0.5 font-mono text-xs font-medium text-text-secondary"
259	          >
260	            {dep}
261	          </span>
262	        ))}
263	      </div>
264	    </section>
265	  );
266	}
267	
268	function TaskExecutionSection({ task }: { task: TaskDetail }) {
269	  const { execution } = task;
270	  if (!execution) return null;
271	
272	  const actorType = execution.actor_type;
273	  const ActorIcon = actorType === "agent" ? Bot : User;
274	  const lastUpdatedAt = execution.last_updated_at;
275	  const lastUpdatedBy = execution.last_updated_by;
276	
277	  return (
278	    <section>
279	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
280	        Execution
281	      </h2>
282	      <div data-task-execution className="grid grid-cols-2 gap-x-8 gap-y-5">
283	        <MetaField
284	          icon={<ActorIcon className="h-4 w-4" aria-hidden="true" />}
285	          label="Actor"
286	        >
287	          <span className="capitalize text-text-primary">
288	            {actorType || <NoneValue />}
289	          </span>
290	        </MetaField>
291	
292	        {lastUpdatedBy && (
293	          <MetaField label="Last Updated By">
294	            <span className="text-text-primary">{lastUpdatedBy}</span>
295	          </MetaField>
296	        )}
297	
298	        {lastUpdatedAt && (
299	          <MetaField label="Last Updated">
300	            <span className="text-text-primary">
301	              {formatTimestamp(lastUpdatedAt)}
302	            </span>
303	          </MetaField>
304	        )}
305	      </div>
306	    </section>
307	  );
308	}
309	
310	type PrEntry = {
311	  label: string;
312	  repo?: string | null;
313	  url?: string | null;
314	  status?: string | null;
315	};
316	
317	function TaskPrRefsSection({ task }: { task: TaskDetail }) {
318	  const entriesByUrl = new Map<string, PrEntry>();
319	
320	  function addEntry(entry: PrEntry) {
321	    if (!entry.url || entriesByUrl.has(entry.url)) return;
322	    entriesByUrl.set(entry.url, entry);
323	  }
324	
325	  for (const ref of task.pr_refs ?? []) {
326	    addEntry({
327	      label: ref.label || ref.repo || "PR",
328	      repo: ref.repo,
329	      url: ref.url,
330	      status: ref.status,
331	    });
332	  }
333	
334	  if (task.pr?.url) {
335	    addEntry({
336	      label: "Repository PR",
337	      repo: task.repo,
338	      url: task.pr.url,
339	      status: task.pr.status,
340	    });
341	  }
342	
343	  if (task.workspace_pr?.url) {
344	    addEntry({
345	      label: "Workspace PR",
346	      url: task.workspace_pr.url,
347	      status: task.workspace_pr.status,
348	    });
349	  }
350	
351	  const allEntries = Array.from(entriesByUrl.values());
352	
353	  if (allEntries.length === 0) return null;
354	
355	  return (
356	    <section>
357	      <h2 className="mb-4 text-xs font-semibold uppercase tracking-widest text-text-muted">
358	        Pull Requests
359	      </h2>
360	      <div data-task-pr-refs className="flex flex-col gap-2">
361	        {allEntries.map((entry, i) => (
362	          <PrRefCard key={entry.url ?? `empty-${i}`} entry={entry} />
363	        ))}
364	      </div>
365	    </section>
366	  );
367	}
368	
369	type TaskActivityTimelineEntry = NonNullable<TaskDetail["activity"]>[number] & {
370	  sortTime: number;
371	  sequence: number;
372	};
373	
374	function TaskActivityTimelineSection({ task }: { task: TaskDetail }) {
375	  const entries = getSortedTaskActivityEntries(task.activity);
376	
377	  return (
378	    <section>
379	      <h2 className="mb-4 border-b border-border pb-3 text-sm font-semibold text-text-primary">
380	        Activity Timeline
381	      </h2>
382	      {entries.length > 0 ? (
383	        <ol data-task-activity-timeline className="flex flex-col gap-0">
384	          {entries.map((entry, index) => (
385	            <TaskActivityTimelineItem
386	              key={`${entry.occurred_at}-${entry.action}-${index}`}
387	              entry={entry}
388	              isLast={index === entries.length - 1}
389	            />
390	          ))}
391	        </ol>
392	      ) : (
393	        <p className="text-sm italic text-text-muted">
394	          No activity logs available.
395	        </p>
396	      )}
397	    </section>
398	  );
399	}
400	
401	function getSortedTaskActivityEntries(
402	  activity: TaskDetail["activity"],
403	): TaskActivityTimelineEntry[] {
404	  if (!activity || activity.length === 0) return [];
405	
406	  return activity
407	    .map((entry, sequence) => {
408	      const entryTime = new Date(entry.occurred_at).getTime();
409	      return {
410	        ...entry,
411	        sequence,
412	        sortTime: Number.isNaN(entryTime)
413	          ? Number.NEGATIVE_INFINITY
414	          : entryTime,
415	      };
416	    })
417	    .sort((a, b) => {
418	      if (a.sortTime !== b.sortTime) return b.sortTime - a.sortTime;
419	      return a.sequence - b.sequence;
420	    });
421	}
422	
423	function getTimelineStatusKey(action: string): string {
424	  if (action === "started" || action === "claimed") return "in_progress";
425	  if (action === "moved_to_review") return "in_review";
426	  return action;
427	}
428	
429	function ActivityNoteText({ text }: { text: string }) {
430	  const tokens = tokenizeText(text);
431	  return (
432	    <>
433	      {tokens.map((token, i) =>
434	        token.type === "link" ? (
435	          <a
436	            key={i}
437	            href={token.href}
438	            target="_blank"
439	            rel="noopener noreferrer"
440	            className="text-primary underline hover:opacity-80"
441	            data-task-activity-link
442	          >
443	            {token.label}
444	          </a>
445	        ) : (
446	          <span key={i}>{token.value}</span>
447	        ),
448	      )}
449	    </>
450	  );
451	}
452	
453	function TaskActivityTimelineItem({
454	  entry,
455	  isLast,
456	}: {
457	  entry: TaskActivityTimelineEntry;
458	  isLast: boolean;
459	}) {
460	  const statusStyle = getStatusStyle(getTimelineStatusKey(entry.action));
461	
462	  return (
463	    <li data-task-timeline-entry className="flex gap-4">
464	      <div className="flex flex-col items-center pt-1">
465	        <span
466	          className={"h-1.5 w-1.5 rounded-full " + statusStyle.dot}
467	          aria-hidden="true"
468	        />
469	        {isLast ? null : (
470	          <span className="mt-1 w-px flex-1 bg-border" aria-hidden="true" />
471	        )}
472	      </div>
473	      <div className="flex min-w-0 flex-1 flex-col gap-1 pb-5">
474	        <div className="flex min-w-0 items-center justify-between gap-4">
475	          <span className="text-sm font-semibold capitalize text-text-primary">
476	            {formatStatusLabel(entry.action)}
477	          </span>
478	          <span className="shrink-0 text-xs text-text-muted">
479	            {formatTimestamp(entry.occurred_at)}
480	          </span>
481	        </div>
482	        <span className="text-xs text-text-muted">by {entry.actor}</span>
483	        {entry.note ? (
484	          <p className="mt-2 border border-border bg-surface px-3 py-2 text-sm text-text-secondary">
485	            <ActivityNoteText text={entry.note} />
486	          </p>
487	        ) : null}
488	      </div>
489	    </li>
490	  );
491	}
492	
493	function PrRefCard({ entry }: { entry: PrEntry }) {
494	  const label = entry.label || entry.repo || "PR";
495	  const hasUrl = typeof entry.url === "string" && entry.url.length > 0;
496	
497	  if (hasUrl) {
498	    return (
499	      <a
500	        href={entry.url!}
501	        target="_blank"
502	        rel="noreferrer noopener"
503	        data-pr-ref={entry.url}
504	        className="flex items-center justify-between border border-border bg-surface px-3 py-2.5 transition-colors hover:border-primary-light hover:bg-surface-subtle"
505	      >
506	        <div className="flex items-center gap-2">
507	          <GitPullRequest className="h-4 w-4 text-success" aria-hidden="true" />
508	          <span className="text-sm font-medium text-text-primary">{label}</span>
