518	  return (
519	    <div
520	      aria-disabled="true"
521	      className="pointer-events-none flex items-center justify-between border border-border bg-surface px-3 py-2.5 opacity-70"
522	    >
523	      <div className="flex items-center gap-2">
524	        <span className="text-text-muted">
525	          <GitPullRequest className="h-4 w-4" aria-hidden="true" />
526	        </span>
