"use client";

import { ArrowRight } from "lucide-react";
import { useRef, useState, useEffect } from "react";
import type { ParsedTask } from "@/services/yaml-parser";
import { getNextAction } from "../../lib/status";
import { formatTimestamp } from "@/lib/time";

type TaskCardProps = {
  task: ParsedTask;
  featureId: string;
  featureTitle: string;
  onOpenTab?: (task: ParsedTask) => void;
  onOpenNewTab?: (task: ParsedTask) => void;
};

export function TaskCard({
  task,
  featureId,
  featureTitle,
  onOpenTab,
  onOpenNewTab,
}: TaskCardProps) {
  const nextAction = getNextAction(task.status);

  const [menuPosition, setMenuPosition] = useState<{
    x: number;
    y: number;
  } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const menuOpen = Boolean(menuPosition);

  useEffect(() => {
    if (!menuOpen) return;

    function handlePointerDown(event: PointerEvent) {
      if (!menuRef.current?.contains(event.target as Node)) {
        setMenuPosition(null);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setMenuPosition(null);
      }
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [menuOpen]);

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      onOpenTab?.(task);
    }
  }

  function handleContextMenu(e: React.MouseEvent) {
    if (!onOpenNewTab) return;
    e.preventDefault();
    e.stopPropagation();
    setMenuPosition({ x: e.clientX, y: e.clientY });
  }

  function handleNewTab(e: React.MouseEvent) {
    e.stopPropagation();
    if (onOpenNewTab) {
      onOpenNewTab(task);
    }
    setMenuPosition(null);
  }

  function handleClick() {
    onOpenTab?.(task);
  }

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onContextMenu={handleContextMenu}
      aria-haspopup="menu"
      aria-expanded={menuOpen}
      data-task-id={task.id}
      className="relative h-full min-h-19 cursor-pointer border border-border bg-surface p-3 transition-colors hover:border-primary hover:bg-surface-secondary focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-surface"
      aria-label={`Task ${task.id}: ${task.title}`}
    >
      <div className="mb-1 flex items-start gap-1">
        <span className="shrink-0 text-xs font-medium text-text-muted">
          {task.id}
        </span>
      </div>
      <p className="mb-2 text-xs font-medium leading-snug text-text-primary line-clamp-2">
        {task.title}
      </p>
      {nextAction && (
        <div className="flex min-w-0 items-center gap-1">
          <ArrowRight
            className="h-3 w-3 shrink-0"
            style={{ color: "#009252" }}
            aria-hidden="true"
          />
          <span className="truncate text-xs text-text-secondary">
            {nextAction}
          </span>
        </div>
      )}
      {task.updatedAt && (
        <p
          className="mt-1 truncate text-xs text-text-muted"
          data-task-updated-at={task.updatedAt}
        >
          {formatTimestamp(task.updatedAt)}
        </p>
      )}

      {menuOpen && menuPosition && (
        <div
          ref={menuRef}
          role="menu"
          className="fixed z-50 w-32 border border-border bg-surface p-1 shadow-lg"
          style={{ top: menuPosition.y, left: menuPosition.x }}
        >
          <button
            type="button"
            role="menuitem"
            onClick={handleNewTab}
            className="flex w-full items-center gap-2 px-2 py-1.5 text-xs text-text-primary transition-colors hover:bg-surface-subtle"
          >
            New tab
          </button>
        </div>
      )}
    </div>
  );
}

"use client";

import { getNextAction } from "@/features/board/lib/status";
import { useLastUpdatedTimer } from "@/features/board/hooks/useLastUpdatedTimer";
import { createSingleDoubleClickController } from "@/lib/click-intent";
import { computeLastUpdatedLabel, computeStatusAge } from "@/lib/time";
import type { ParsedFeature, ParsedTask } from "@/services/yaml-parser";
import { ArrowRight, Bot, Layers } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";

export type TaskTrackingItemProps = {
  task: ParsedTask;
  feature: ParsedFeature;
  onSelect: (task: ParsedTask, feature: ParsedFeature) => void;
  onOpenTab?: (task: ParsedTask) => void;
  onOpenNewTab?: (task: ParsedTask) => void;
};

const ACTOR_TYPE_LABEL: Record<string, string> = {
  agent: "Agent",
  human: "Human",
  either: "Agent or Human",
};

export function TaskTrackingItem({
  task,
  feature,
  onSelect,
  onOpenTab,
  onOpenNewTab,
}: TaskTrackingItemProps) {
  const actorLabel = task.execution?.actor_type
    ? (ACTOR_TYPE_LABEL[task.execution.actor_type] ?? task.execution.actor_type)
    : null;

  const statusAge = computeStatusAge(task);

  useLastUpdatedTimer();
  const lastUpdatedLabel = computeLastUpdatedLabel(task);

  const priorityLabel = task.priority?.trim()
    ? task.priority.trim().toUpperCase()
    : null;

  const nextInfo = task.description?.trim()
    ? task.description
    : task.blockedReason
      ? task.blockedReason
      : getNextAction(task.status);

  const clickController = useMemo(
    () =>
      createSingleDoubleClickController({
        onSingleClick: () => onSelect(task, feature),
        onDoubleClick: () => {
          if (onOpenTab) {
            onOpenTab(task);
          }
        },
      }),
    [feature, onOpenTab, onSelect, task],
  );

  useEffect(() => clickController.clearPendingClick, [clickController]);

  const [menuPosition, setMenuPosition] = useState<{
    x: number;
    y: number;
  } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const menuOpen = Boolean(menuPosition);

  useEffect(() => {
    if (!menuOpen) return;

    function handlePointerDown(event: PointerEvent) {
      if (!menuRef.current?.contains(event.target as Node)) {
        setMenuPosition(null);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setMenuPosition(null);
      }
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [menuOpen]);

  function handleDoubleClick(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    clickController.handleDoubleClick();
  }

  function handleContextMenu(e: React.MouseEvent) {
    if (!onOpenNewTab) return;
    e.preventDefault();
    e.stopPropagation();
    setMenuPosition({ x: e.clientX, y: e.clientY });
  }

  function handleNewTab(e: React.MouseEvent) {
    e.stopPropagation();
    if (onOpenNewTab) {
      onOpenNewTab(task);
    }
    setMenuPosition(null);
  }

  return (
    <button
      type="button"
      onClick={clickController.handleClick}
      onDoubleClick={handleDoubleClick}
      onContextMenu={handleContextMenu}
      aria-haspopup="menu"
      aria-expanded={menuOpen}
      className="group flex w-full flex-col gap-2 border border-border bg-surface px-3 py-3 text-left transition-colors hover:border-primary-light hover:bg-surface-subtle focus:outline-none focus-visible:border-primary focus-visible:bg-primary-light/30"
    >
      <div className="flex min-w-0 items-start gap-2">
        <span
          aria-label={`Task ${task.id}`}
          className="shrink-0 border border-primary-light bg-primary-light px-2 py-0.5 font-mono text-[11px] font-bold leading-4 text-primary"
        >
          {task.id}
        </span>
        <p className="line-clamp-2 min-w-0 text-xs font-semibold leading-snug text-text-primary">
          {task.title || "Untitled task"}
        </p>
      </div>
      <div className="flex min-w-0 flex-wrap items-center gap-1.5 text-[10px] leading-4 text-text-secondary">
        <span className="flex max-w-full items-center gap-1 bg-chip-bg px-1.5">
          <Layers className="h-2.5 w-2.5 shrink-0 text-text-secondary" />
          <span className="truncate">{feature.title || feature.id}</span>
        </span>
        {statusAge !== "—" && (
          <span
            aria-label={`Status age: ${statusAge}`}
            className="border border-border bg-surface px-1.5 font-mono font-bold text-text-primary"
          >
            {statusAge}
          </span>
        )}
        {lastUpdatedLabel && (
          <span
            aria-label={`Last updated: ${lastUpdatedLabel}`}
            className="border border-border bg-surface px-1.5 font-mono text-text-secondary"
          >
            {lastUpdatedLabel}
          </span>
        )}
        {priorityLabel && (
          <span className="bg-chip-bg px-1.5 font-mono text-text-secondary">
            {priorityLabel}
          </span>
        )}
        {actorLabel && (
          <span className="flex items-center gap-1 bg-chip-bg px-1.5">
            <Bot className="h-2.5 w-2.5 shrink-0 text-ready" />
            {actorLabel}
          </span>
        )}
      </div>
      {nextInfo && (
        <p className="flex min-w-0 items-center gap-1 text-[10px] leading-4 text-text-muted">
          <ArrowRight className="h-3 w-3 shrink-0 text-success" />
          <span className="truncate">{nextInfo}</span>
        </p>
      )}

      {menuOpen && menuPosition && (
        <div
          ref={menuRef}
          role="menu"
          className="fixed z-50 w-32 border border-border bg-surface p-1 shadow-lg"
          style={{ top: menuPosition.y, left: menuPosition.x }}
        >
          <button
            type="button"
            role="menuitem"
            onClick={handleNewTab}
            className="flex w-full items-center gap-2 px-2 py-1.5 text-xs text-text-primary transition-colors hover:bg-surface-subtle"
          >
            New tab
          </button>
        </div>
      )}
    </button>
  );
}

"use client";

import { Clock3 } from "lucide-react";
import { useRef, useState, useEffect } from "react";
import type { ParsedFeature } from "@/services/yaml-parser";
import {
  formatTimestamp,
  getFeatureLastModifiedAt,
  isTodayTimestamp,
} from "@/lib/time";

type FeatureListRowProps = {
  feature: ParsedFeature;
  onClick: () => void;
  onOpenNewTab?: () => void;
};

export function FeatureListRow({
  feature,
  onClick,
  onOpenNewTab,
}: FeatureListRowProps) {
  const lastModifiedAt = getFeatureLastModifiedAt(feature);
  const modifiedToday = lastModifiedAt
    ? isTodayTimestamp(lastModifiedAt)
    : false;
  const totalTasks = feature.taskCounts?.total ?? feature.tasks.length;
  const taskCountLabel = `${totalTasks} ${totalTasks === 1 ? "task" : "tasks"}`;

  const [menuPosition, setMenuPosition] = useState<{
    x: number;
    y: number;
  } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const menuOpen = Boolean(menuPosition);

  useEffect(() => {
    if (!menuOpen) return;

    function handlePointerDown(event: PointerEvent) {
      if (!menuRef.current?.contains(event.target as Node)) {
        setMenuPosition(null);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setMenuPosition(null);
      }
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [menuOpen]);

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      onClick();
    }
  }

  function handleContextMenu(e: React.MouseEvent) {
    if (!onOpenNewTab) return;
    e.preventDefault();
    e.stopPropagation();
    setMenuPosition({ x: e.clientX, y: e.clientY });
  }

  function handleNewTab(e: React.MouseEvent) {
    e.stopPropagation();
    if (onOpenNewTab) {
      onOpenNewTab();
    }
    setMenuPosition(null);
  }

  return (
    <div
      data-feature-card-status={feature.featureStatus}
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      onContextMenu={handleContextMenu}
      aria-haspopup="menu"
      aria-expanded={menuOpen}
      aria-label={`Open feature tab for ${feature.title || feature.id}`}
      className="flex h-full min-h-[82px] w-full cursor-pointer flex-col gap-2 border border-border bg-surface px-3 py-3 text-left transition-colors hover:bg-surface-subtle focus-visible:outline focus-visible:outline-2 focus-visible:outline-primary"
    >
      {/* Title — primary text area, wraps before truncating */}
      <div className="min-w-0 flex-1">
        <p
          className="line-clamp-2 text-sm font-semibold text-text-primary"
          title={feature.title || feature.id}
        >
          {feature.title || feature.id}
        </p>
      </div>

      {/* Feature ID — compact secondary metadata below title */}
      {feature.title && feature.title !== feature.id && (
        <p
          className="truncate text-[11px] font-medium uppercase tracking-wide text-text-muted"
          title={feature.id}
        >
          {feature.id}
        </p>
      )}

      <div className="mt-auto flex min-w-0 items-center gap-3 text-xs text-text-muted">
        <span className="shrink-0">{taskCountLabel}</span>
        {lastModifiedAt && (
          <span
            data-feature-modified-at={lastModifiedAt}
            data-modified-today={modifiedToday ? "true" : "false"}
            className={
              "flex min-w-0 shrink-0 items-center gap-1.5 rounded px-1.5 py-0.5 text-xs " +
              (modifiedToday
                ? "bg-success-bg font-semibold text-success"
                : "text-text-muted")
            }
            title={`Modified ${lastModifiedAt}`}
          >
            <Clock3 className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
            <span className="truncate">{formatTimestamp(lastModifiedAt)}</span>
          </span>
        )}
      </div>

      {menuOpen && menuPosition && (
        <div
          ref={menuRef}
          role="menu"
          className="fixed z-50 w-32 border border-border bg-surface p-1 shadow-lg"
          style={{ top: menuPosition.y, left: menuPosition.x }}
        >
          <button
            type="button"
            role="menuitem"
            onClick={handleNewTab}
            className="flex w-full items-center gap-2 px-2 py-1.5 text-xs text-text-primary transition-colors hover:bg-surface-subtle"
          >
            New tab
          </button>
        </div>
      )}
    </div>
  );
}

